{"seed_id":"MKT-105","slug":"aloun-country-market","name":"Aloun Country Market","kind":"farm_stand","area":"Central","venue_name":"Aloun Farms","address":"94-488 Kunia Rd, Waipahu, HI 96797","frequency":"biweekly","schedule_text":"2nd and 4th Saturdays of every month (hours on flyer image, not captured)","organizer_name":"Aloun Farms","website":"https://alounfarms.com/pages/aloun-country-market-1","instagram":"https://instagram.com/alounfarmshawaii","facebook":"https://facebook.com/AlounFarmsHawaii","research_notes":"On-farm market of local seasonal produce; address from Honolulu Magazine pumpkin guide.","status":"active","confidence":"medium","source_url":"https://www.alounfarms.com/"}]$j$::jsonb)
    as x(seed_id text, slug text, name text, kind text, area text, venue_name text, address text, frequency text, schedule_text text, organizer_name text, website text, instagram text, facebook text, accepts_snap boolean, da_bux boolean, admission text, parking_notes text, vendor_count_est text, vendor_application_url text, booth_fee text, research_notes text, status text, confidence text, source_url text, source_date text, sessions jsonb)
), ins as (
  insert into markets (seed_id, slug, name, island_id, kind, area, venue_name, address, frequency, schedule_text, organizer_name, website, instagram, facebook, accepts_snap, da_bux, admission, parking_notes, vendor_count_est, vendor_application_url, booth_fee, research_notes, status, confidence, source_url, source_date, publish_status)
  select d.seed_id, d.slug, d.name, (select id from islands where slug = 'oahu'), d.kind, d.area, d.venue_name, d.address, d.frequency, d.schedule_text, d.organizer_name, d.website, d.instagram, d.facebook, d.accepts_snap, d.da_bux, d.admission, d.parking_notes, d.vendor_count_est, d.vendor_application_url, d.booth_fee, d.research_notes, d.status, d.confidence, d.source_url, d.source_date, 'draft'
  from d
  returning id, seed_id
)
insert into market_sessions (market_id, day_of_week, starts, ends)
select ins.id, (s ->> 0)::smallint, (s ->> 1)::time, (s ->> 2)::time
from ins join d using (seed_id), jsonb_array_elements(d.sessions) s
where d.sessions is not null;

