insert into market_sessions (market_id, day_of_week, starts, ends)
select ins.id, (s ->> 0)::smallint, (s ->> 1)::time, (s ->> 2)::time
from ins join d using (seed_id), jsonb_array_elements(d.sessions) s
where d.sessions is not null;

