-- Links ----------------------------------------------------------------------

-- A vendor's "seen at" text links to a market only on an exact name match.
insert into market_vendors (market_id, vendor_id)
select m.id, v.id
from vendors v
join markets m on lower(m.name) = lower(v.markets_seen_at)
where v.seed_id is not null
on conflict do nothing;

-- A market's organizer links only on an exact name match.
update markets m set organizer_id = o.id
from organizers o
where m.organizer_id is null
  and m.organizer_name is not null
  and lower(m.organizer_name) = lower(o.name);

-- Provenance: the research pass read each row's listed source on 2026-10-23.
insert into verification_events (subject_type, subject_id, verified_at, method, note)
select 'market', id, timestamptz '2026-10-23 09:00:00-10', 'source_check',
       $t$research pass read the listed source$t$
from markets
where seed_id is not null and publish_status = 'draft' and source_url is not null;

insert into verification_events (subject_type, subject_id, verified_at, method, note)
select 'vendor', id, timestamptz '2026-10-23 09:00:00-10', 'source_check',
       $t$research pass read the listed source$t$
from vendors
where seed_id is not null and publish_status = 'draft' and source_url is not null;
